import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/festivals/vaikuntha-ekadashi/',[('','Vaikuṇṭha Ekādaśī','The Day the Northern Gate Opens')],'blue','Vaikuṇṭha Ekādaśī','Lord','Vaikuṇṭha Ekādaśī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/vaikuntha-ekadashi/'
i=0
V=lambda: vishnu()
def gate(open_=True): return '<rect x="-50" y="-110" width="100" height="110" fill="#c9a06a"/><path d="M-50 -110 q50 -40 100 0" fill="#e0a800"/>'+('<path d="M-36 0 v-90 h28 v90z M8 0 v-90 h28 v90z" fill="#8a5a3a"/>' if not open_ else '<path d="M-36 0 v-90 h10 v90z M26 0 v-90 h10 v90z" fill="#8a5a3a"/><rect x="-26" y="-90" width="52" height="90" fill="#fff8d0"/>')
def queue(n=6): return ''.join(g(k*22,0,.6,person(['#c0392b','#2a5aa8','#e0a800','#2a9d6f'][k%4])) for k in range(n))
def tower(): return '<path d="M-30 0 v-30 h60 v30z M-24 -30 v-24 h48 v24z M-18 -54 v-20 h36 v20z M-10 -74 v-14 h20 v14z" fill="#d8b878"/>'
def araiyar(): return person('#c0392b')+'<path d="M-8 -52 l8 -24 l8 24z" fill="#e0a800"/>'
COV=covart('A temple’s northern gate thrown open before dawn, light streaming out, with a long line of devotees and a gopuram behind',f'<rect width="440" height="196" fill="#20243a"/>'+''.join(f'<circle cx="{(37*k)%440}" cy="{(23*k*k)%90+8}" r="1.4" fill="#fff8d0" stroke="none"/>' for k in range(1,18))+g(300,150,1.2,tower())+'<rect y="170" width="440" height="26" fill="#3a4a6a"/>'+g(220,180,1.3,gate())+'<path d="M190 180 l-60 16 h180 l-60 -16z" fill="#fff8d0" opacity=".35" stroke="none"/>'+g(30,180,1,queue(6))+g(380,170,.6,sun(14)))
pp=[foreword(i,['Of the twenty-four Ekādaśīs of the year, one is the greatest in the South: <b>Vaikuṇṭha Ekādaśī</b>, the bright eleventh of Mārgaśīrṣa, in the month of Dhanus. Before dawn, in every Viṣṇu temple, a gate on the northern side that stays shut all year is thrown open: the <b>Vaikuṇṭha dvāra</b>, the door of Viṣṇu’s heaven. Millions queue through the night at Tirumala, Śrīraṅgam and their own town temples to pass through it.','The same day is <b>Mokṣadā Ekādaśī</b> in the north and <b>Gītā Jayantī</b>, the day the Gītā was spoken. This article explains the Ekādaśī itself and its goddess, the best of months, the gate and why it opens, the twenty-one-day festival of Śrīraṅgam with the songs of the Āḻvārs, Tirumala, the fast and the vigil, and gives three verses for the day.'],[('z','Walking through a door gets you to heaven?'),('b','It’s a picture of what the day means, Zappy: the gate of liberation opens. Keep reading and you’ll see why people queue all night.')]),
 glance([('Names','Vaikuṇṭha Ekādaśī; Mukkoṭi Ekādaśī (Kannada, Telugu); Svargavāsal Ekādaśī (Tamil, Kerala); Mokṣadā Ekādaśī (north)'),('When','Śukla Ekādaśī of Mārgaśīrṣa, falling in the solar month of Dhanus (Mārgaḻi); December–January'),('Same day','Gītā Jayantī'),('Main rite','Darśan through the northern gate, the Vaikuṇṭha dvāra, before dawn'),('Vow','Fast, night vigil, Viṣṇu’s names; pāraṇa on Dvādaśī morning'),('Great centres','Śrīraṅgam (Adhyayana Utsava), Tirumala, Bhadrācalam, and every Viṣṇu temple'),('Karnataka','Vaikuṇṭha dvāras at Bengaluru’s Veṅkaṭeśvara temples, Mēlukōṭe, Śrīraṅgapaṭṇa')],svg(560,140,'A gate opening before dawn',f'<rect width="560" height="140" fill="#20243a"/>'+g(280,130,1,gate())+g(80,130,.9,queue(5))+g(420,130,.8,tower()))),
 reading('ekadashi','WHAT IS EKĀDAŚĪ?','The eleventh day and its fast',svg(560,160,'Fifteen moon phases with the eleventh circled',f'<rect width="560" height="160" fill="#20243a"/>'+''.join(f'<circle cx="{30+k*35}" cy="70" r="13" fill="{"#fff8d0" if k<11 else "#cfd8e6"}" stroke="#111" stroke-width="1.5"/>' for k in range(15))+'<circle cx="380" cy="70" r="19" fill="none" stroke="#ffd60a" stroke-width="3"/>'+lab(380,115,'11th: Ekādaśī').replace('#111','#fff8d0')),['<b>Twice a month.</b> Ekādaśī, the eleventh lunar day of each fortnight, comes about twenty-four times a year. Each is sacred to Viṣṇu and has its own name and story; read our '+L('/festivals/ekadashi/','Ekādaśī series')+' for all of them.','<b>The fast.</b> Grains, rice above all, are given up; many fast fully, some without water. The night is kept in vigil, and the fast is broken on <b>Dvādaśī</b>, the twelfth day, within a fixed morning window (<b>pāraṇa</b>).','<b>Who keeps it.</b> Ekādaśī is the most widely kept fast in India: Vaiṣṇavas above all, but also Śaiva and Smārta homes, and many who keep no other fast. Karnataka’s Haridāsas sang its praise; Maharashtra’s Vārkarīs walk to Paṇḍharpur for it.','<b>The greatest of them.</b> In the South the Ekādaśī of the bright half of Mārgaśīrṣa, in Dhanurmāsa, is the one when Vaikuṇṭha’s gate opens. It is said to carry the merit of all the others.'],[('z','Why does this one count most?'),('b','Of twenty-four Ekādaśīs a year, this is the one when the gate is opened, Zappy. The rest are steps; this is the door.')],'Twenty-four steps, <b>one door</b>.'),
 story('mura','THE GODDESS EKĀDAŚĪ','Why the eleventh day is holy',strip('Three panels: Viṣṇu resting in a cave; a radiant goddess springing from him to fight the demon Mura; Viṣṇu blessing her',[panel([(sheshashayi(),.6)],'#3a3a5a',150),panel([(devi(sari='#2a5aa8',items=('sword','discus')),.9),(demon('#2a3a5a'),.9)],'#fde4e4',150),panel([(V(),.9),(devi(sari='#2a5aa8',items=('lotus',)),.8)],'#fff3cf',150)],['Viṣṇu rests','the goddess fights','her day named']),'Padma Purāṇa (Uttara Khaṇḍa), the Ekādaśī māhātmya; told in full in our '+L('/festivals/ekadashi/utpanna/','Utpannā Ekādaśī')+' article.',['The demon <b>Mura</b> had driven the gods from heaven. Viṣṇu fought him for ages, then, weary, withdrew to rest in a cave called Haimavatī.','Mura followed to kill the sleeping Lord. At that moment a radiant goddess sprang from Viṣṇu’s body, armed and blazing, and challenged the demon.','With a single sound of “huṃ” she reduced Mura to ashes.','Viṣṇu woke and asked who she was. Because she had appeared on the eleventh lunar day, he named her <b>Ekādaśī</b>.','He promised that whoever fasts on her day would be freed from sin and reach his abode. So every Ekādaśī is her day, and Vaikuṇṭha Ekādaśī the greatest of them.'],[('z','A goddess called Ekādaśī?'),('b','Born from Viṣṇu’s body while he slept, Zappy. She saved him, and he made her day holy.')],'The day <b>is a goddess</b>.'),
 verse('v-month','Bhagavad Gītā 10.35','Of months, I am Mārgaśīrṣa',['bṛhatsāma tathā sāmnāṃ gāyatrī chandasām aham','māsānāṃ mārgaśīrṣo ’ham ṛtūnāṃ kusumākaraḥ'],svg(200,150,'A calendar circle with one month glowing at the dawn position',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,75,1,'<circle r="55" fill="#fff8e7"/>'+''.join(f'<circle cx="{45*__import__("math").cos(k*0.52-1.57):.1f}" cy="{45*__import__("math").sin(k*0.52-1.57):.1f}" r="{9 if k==0 else 5}" fill="{"#ffd60a" if k==0 else "#c9d6e6"}"/>' for k in range(12)))),'Of the Sāman chants I am the Bṛhat Sāman; of metres, the Gāyatrī; of months, I am Mārgaśīrṣa; of seasons, the flower-bearing spring.',[('bṛhat-sāma','the Bṛhat Sāman chant'),('gāyatrī','the Gāyatrī metre'),('chandasām','of metres'),('māsānām','of months'),('mārgaśīrṣaḥ','Mārgaśīrṣa'),('kusumākaraḥ','spring, the flower-maker')],'<b>The best of months.</b> In the Gītā’s tenth chapter Kṛṣṇa names the best of each kind and calls himself Mārgaśīrṣa among months. The solar month of Dhanus, which overlaps it, is held to be the gods’ dawn: the six months of the sun’s southward course are their night. So the month is given to dawn worship (read our '+L('/festivals/dhanurmasa/','Dhanurmāsa')+' series), and its Ekādaśī opens the gate.',k='<b>The best of months</b>, the gods’ dawn.',note='Text as on our '+L('/vishnu/bhagavad-gita/chapter-10/','Gītā, chapter 10')+' page.'),
 reading('gate','THE NORTHERN GATE','The Vaikuṇṭha dvāra',svg(560,170,'A temple plan with the sanctum and a gate on the north side marked open',f'<rect width="560" height="170" fill="#fffaf0"/>'+'<rect x="180" y="20" width="200" height="130" fill="#e3eaf3" stroke="#111" stroke-width="2"/><rect x="250" y="60" width="60" height="50" fill="#c9a06a"/>'+lab(280,90,'sanctum')+'<rect x="260" y="14" width="40" height="12" fill="#ffd60a"/>'+lab(280,10,'north gate: open')+'<path d="M280 26 v30" stroke="#c0392b" stroke-width="2" stroke-dasharray="4 3"/>'+lab(280,165,'south: main entrance')+lab(470,85,'N ↑')),['<b>What it is.</b> On the north side of the temple a door or passage is kept shut all year. Before dawn on Vaikuṇṭha Ekādaśī it is opened, and devotees enter or leave the sanctum’s circuit through it: the <b>Vaikuṇṭha dvāra</b>, called <b>Paramapada vāsal</b> at Śrīraṅgam, <b>Svargavāsal</b> in Tamil.','<b>What it means.</b> A Viṣṇu temple is built as an image of Vaikuṇṭha, and the northern gate stands for the passage from this world to his abode. Passing through it is a foretaste of liberation, staged for the living.','<b>Everywhere.</b> Temples that have no permanent north gate set up a decorated one for the day, so that devotees in every town can walk through. In Karnataka the Veṅkaṭeśvara temples of Bengaluru, Mēlukōṭe, Śrīraṅgapaṭṇa and countless village temples do so.','<b>The welcome.</b> Śrīvaiṣṇavas recall Nammāḻvār’s hymn of the soul’s arrival in Vaikuṇṭha, where the gods line the way and the doors are thrown open. The temple rite enacts that welcome.'],[('z','Why the north?'),('b','North is the direction of the gods and of the sun’s bright path, Zappy. Read our Saṅkrānti article for why.')],'The door that <b>opens once a year</b>.'),
 story('madhu','WHY THE GATE OPENS','The story told in temples',strip('Three panels: two demons born from Viṣṇu’s ear during his sleep; their fight with Viṣṇu; the defeated demons asking a boon at a gate',[panel([(sheshashayi(),.6),(demon(),.5),(demon('#6a2a2a'),.5)],'#dfe9f6',150),panel([(V(),.9),(demon(),.8)],'#fde4e4',150),panel([(gate(),.6),(demon(),.6),(demon('#6a2a2a'),.6)],'#fff3cf',150)],['Madhu and Kaiṭabha','the long fight','a gate for all']),'A South Indian temple tradition; the Purāṇic support is indirect.',['During Viṣṇu’s cosmic sleep two demons, <b>Madhu</b> and <b>Kaiṭabha</b>, were born from the wax of his ear and set out to destroy Brahmā on the lotus.','Viṣṇu woke and fought them for five thousand years, the Purāṇas say, and finally slew them on his thighs. (The Devī Māhātmya tells the same battle; read our '+L('/devi/devi-mahatmya/','Devī Māhātmya')+'.)','The temple telling continues: touched by the Lord, the demons repented and asked for one thing: that a gate of Vaikuṇṭha be opened, and that whoever saw Viṣṇu coming through it on this day should reach his abode.','Viṣṇu granted it. So the northern gate opens on Mārgaśīrṣa Śukla Ekādaśī.','The name <b>Mukkoṭi</b>, “three crores”, says that the thirty-three crore gods throng to Vaikuṇṭha to see Viṣṇu this day; devotees on earth join them.'],[('z','The demons asked for heaven’s gate for everyone?'),('b','That’s the beauty of the telling, Zappy. Even the defeated get a door, and they hold it open for us.')],'Even demons <b>hold the door</b>.'),
 reading('srirangam','ŚRĪRAṄGAM','The twenty-one days of song',svg(560,170,'Śrīraṅgam’s towers with a procession carrying Raṅganātha through a gate at dawn',f'<rect width="560" height="170" fill="#fde9c8"/>'+''.join(g(x,140,s,tower()) for x,s in [(80,1.1),(200,1.4),(360,1.6),(480,1.1)])+'<rect y="140" width="560" height="30" fill="#c9a06a"/>'+g(280,150,.8,gate())+g(280,120,.6,sheshashayi())),['<b>The Adhyayana Utsava.</b> At Śrīraṅgam the day sits in the middle of a twenty-one-day festival: ten days of <b>Pagal Pattu</b> (day) and ten of <b>Rā Pattu</b> (night), in which the <b>Nālāyira Divya Prabandham</b>, the four thousand Tamil verses of the Āḻvārs, is recited in order before Raṅganātha.','<b>Mohinī.</b> On the day before, the festival image, Namperumāḷ, appears as Mohinī, the enchantress who won the nectar for the gods.','<b>The gate.</b> Before dawn on the Ekādaśī, Namperumāḷ, in a dazzling armour of jewels, is carried through the <b>Paramapada vāsal</b>, and the crowds follow. The Rā Pattu nights then carry Nammāḻvār’s Tiruvāymoḻi.','<b>Nammāḻvār’s mokṣa.</b> The festival ends with the enactment of the poet-saint Nammāḻvār reaching Vaikuṇṭha, a moving rite in which his image is carried to the Lord’s feet and covered with tulasī. Tradition credits the tenth-century ācārya <b>Nāthamuni</b> with recovering the hymns and starting the festival. See our '+L('/temples-of-india/triranga/','Triraṅga')+' series.'],[('z','Twenty-one days for one day?'),('b','The day is the peak, Zappy. The festival is the mountain.')],'Four thousand verses, <b>one gate</b>.'),
 cards('araiyar','THE ARAIYAR AND THE ĀḺVĀRS','Song, dance and the poets of Viṣṇu',fig_row('A singer in a tall cap with cymbals, a palm-leaf book, a lamp and Viṣṇu reclining',[(araiyar(),1.1),(book(),1.4),(lamp(),1.6),(sheshashayi(),.6)],['araiyar','Prabandham','lamp','Raṅganātha'],gy=150),[('🎭','Araiyar sēvai','A hereditary art of singing and enacting the Āḻvārs’ hymns with gesture and commentary, wearing tall caps, before the deity. It survives in only a few temples: Śrīraṅgam, Śrīvilliputtūr, Āḻvār Tirunagari.'),('📜','The Āḻvārs','Twelve Tamil poet-saints (sixth to ninth centuries by common dating) whose hymns to Viṣṇu were gathered as the Divya Prabandham; Āṇḍāḷ of the '+L('/festivals/dhanurmasa/andal-tiruppavai/','Tiruppāvai')+' is one of them.'),('🙏','Nammāḻvār','The greatest of them, author of the Tiruvāymoḻi, called the “Tamil Veda” in Śrīvaiṣṇava tradition.'),('🎶','In Karnataka','Mēlukōṭe, where Rāmānujācārya lived for years, keeps the Śrīvaiṣṇava calendar with the Prabandham recited before Celuvanārāyaṇa.')],[('z','Dance as worship?'),('b','The Āḻvārs sang for God, Zappy; the Araiyars still sing them back to him, with their hands too.')],'Poetry <b>sung back to God</b>.'),
 reading('tirumala','TIRUMALA AND THE TELUGU COUNTRY','Mukkoṭi Ekādaśī',svg(560,170,'Seven hills with a temple and a long winding queue',f'<rect width="560" height="170" fill="#e3eaf3"/>'+''.join(g(60+k*75,170,.9,mountain('#7a9a7a',False)) for k in range(7))+g(280,95,.7,tower())+'<path d="M40 160 q120 -40 200 -40 t200 -30" fill="none" stroke="#c0392b" stroke-width="3" stroke-dasharray="3 3"/>'),['<b>The passage.</b> At Tirumala the Vaikuṇṭha dvāram is a passage around the sanctum, normally closed. The temple authority now keeps it open for ten days from Vaikuṇṭha Ekādaśī, with tokens issued in advance, so that more pilgrims can pass through.','<b>Dvādaśī.</b> The next morning the Sudarśana cakra is bathed in the Svāmi Puṣkariṇī tank (<b>cakrasnāna</b>), and pilgrims bathe with it.','<b>Bhadrācalam.</b> In Telaṅgāṇa the Rāma temple of Bhadrācalam holds a famous gate-opening, the <b>uttara dvāra darśana</b>, with Rāma seen through the northern gate.','<b>The crowds.</b> Tirumala’s Vaikuṇṭha Ekādaśī crowds are among the largest single-day gatherings at any temple; Karnataka pilgrims travel by the busload.'],[('z','Ten days instead of one?'),('b','So everyone gets a turn, Zappy. The gate is generous now.')],'The seven hills <b>open the door</b>.'),
 verse('v-shanta','Śāntākāraṃ','The meditation on Viṣṇu',['śāntākāraṃ bhujagaśayanaṃ padmanābhaṃ sureśaṃ','viśvādhāraṃ gaganasadṛśaṃ meghavarṇaṃ śubhāṅgam','lakṣmīkāntaṃ kamalanayanaṃ yogibhir dhyānagamyaṃ','vande viṣṇuṃ bhavabhayaharaṃ sarvalokaikanātham'],svg(200,150,'Viṣṇu reclining on the serpent with a lotus from his navel',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,130,.9,sheshashayi())),'I bow to Viṣṇu: of peaceful form, lying on the serpent, lotus-navelled, lord of the gods, support of the universe, vast as the sky, dark as a rain-cloud, of auspicious limbs, beloved of Lakṣmī, lotus-eyed, reached by yogis in meditation, remover of the fear of worldly life, the one lord of all worlds.',[('śānta-ākāram','of peaceful form'),('bhujaga-śayanam','lying on the serpent'),('padma-nābham','lotus-navelled'),('gagana-sadṛśam','like the sky'),('bhava-bhaya-haram','removing fear of saṃsāra'),('sarva-loka-eka-nātham','sole lord of all worlds')],'<b>The vigil verse.</b> Through the Ekādaśī night devotees keep awake with Viṣṇu’s names. This dhyāna verse, recited before the Viṣṇu Sahasranāma, gives the image to hold: Viṣṇu at peace on Śeṣa, the one who removes the fear of the round of births, which is exactly what the gate promises.',k='The Lord who <b>ends all fear</b>.',note='Text as on our '+L('/vishnu/shantakaram/','Śāntākāraṃ')+' page.'),
 reading('vow','THE FAST AND THE VIGIL','How the day is kept',svg(560,160,'A lamp burning through the night beside a book and a sleeping town, with the dawn breaking',f'<rect width="560" height="160" fill="#20243a"/>'+'<rect x="420" width="140" height="160" fill="#fde9c8" opacity=".25"/>'+g(200,130,2,lamp())+g(300,128,1.5,book())+g(500,60,.8,sun(14))),['<b>Daśamī.</b> The evening before, a single light meal, no grains after.','<b>Ekādaśī.</b> A complete fast for the strong, fruit and milk for others; no rice in any case. Before dawn the gate darśan; through the day Viṣṇu’s names, the Sahasranāma, the Gītā.','<b>Jāgaraṇa.</b> The night is kept awake with bhajans and readings, at home or in the temple. In Karnataka the Haridāsa songs of Purandara Dāsa and Kanaka Dāsa fill the night.','<b>Dvādaśī pāraṇa.</b> The fast is broken next morning in the time window the almanac gives, often with a simple meal of rice, greens and āmalaka, after feeding others first. Many Mādhva homes make a special Dvādaśī meal with agase (flax) and greens.'],[('z','Can children fast?'),('b','A small fast, Zappy: no rice, one meal, a few names. The vigil matters more than the hunger.')],'Fast, wake, <b>and break it well</b>.'),
 verse('v-gita','Bhagavad Gītā 18.66','Gītā Jayantī: the last word',['sarvadharmān parityajya mām ekaṃ śaraṇaṃ vraja','ahaṃ tvā sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ'],svg(200,150,'Kṛṣṇa on a chariot raising his hand to Arjuna',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(70,140,1,god('#2a5aa8'))+g(140,140,1,god('#e0a800'))+'<path d="M40 140 h120 l-10 -30 h-100z" fill="#c9a06a" opacity=".6"/>'),'Giving up all dharmas, take refuge in me alone. I will free you from all sins; do not grieve.',[('sarva-dharmān','all duties, all paths'),('parityajya','giving up'),('mām ekam','in me alone'),('śaraṇaṃ vraja','take refuge'),('mokṣayiṣyāmi','I will free'),('mā śucaḥ','do not grieve')],'<b>Gītā Jayantī.</b> The same Mārgaśīrṣa Ekādaśī is kept as the day Kṛṣṇa spoke the Gītā on the field of Kurukṣetra, and many read the whole Gītā on it. This verse, which Śrīvaiṣṇavas call the <b>carama śloka</b>, the final verse, is the Gītā’s last promise, and it matches the gate: <i>mokṣayiṣyāmi</i>, I will free you.',k='<b>Do not grieve</b>.',note='Text as on our '+L('/vishnu/bhagavad-gita/chapter-18/','Gītā, chapter 18')+' page.'),
 reading('meaning','WHAT THE GATE MEANS','Liberation made visible',svg(560,150,'A gate with light pouring out and a single figure walking into it',f'<rect width="560" height="150" fill="#20243a"/>'+g(300,140,1.1,gate())+'<path d="M270 140 l-80 10 h220 l-80 -10z" fill="#fff8d0" opacity=".3" stroke="none"/>'+g(300,140,.6,person('#2a5aa8'))),['<b>A picture of mokṣa.</b> The Vaikuṇṭha dvāra turns the most abstract idea of Hindu thought, liberation, into a step you can take. Walking through it does not by itself free anyone; it reminds us what the whole of devotion is for. (Interpretation.)','<b>For everyone.</b> In the temple story even the demons Madhu and Kaiṭabha ask for the gate to open for all. The queue is the most democratic sight in India: rich and poor, old and young, in one line through one door.','<b>Grace.</b> The Gītā’s carama śloka and the gate say the same: the door is opened from the other side. Śrīvaiṣṇava teachers make this the heart of their theology. (Interpretation.)','<b>Dawn.</b> The gate opens before sunrise, in the gods’ dawn month: the whole day is about waking up.'],[('z','If I could do one thing for Vaikuṇṭha Ekādaśī?'),('b','Skip the rice, stay awake for one hour of Viṣṇu’s names, and walk through any temple’s north gate at dawn, Zappy, with your whole attention.')],'The door <b>opened from the other side</b>.'),
 end(i,['<b>When.</b> Mārgaśīrṣa Śukla Ekādaśī, in Dhanurmāsa; also Gītā Jayantī.','<b>Ekādaśī.</b> The goddess who slew Mura; the fast, the vigil, the pāraṇa.','<b>Gate.</b> The northern door of Vaikuṇṭha, opened before dawn.','<b>Śrīraṅgam.</b> Twenty-one days of the Āḻvārs’ songs; Nammāḻvār’s mokṣa.','<b>Verses.</b> Gītā 10.35; Śāntākāraṃ; Gītā 18.66.'],'Next: '+L('/festivals/hanuman-jayanti/','Hanumān Jayantī')+', kept in Karnataka in the same month. More: our '+L('/festivals/ekadashi/','Ekādaśī series')+'.','Vaikuṇṭha Ekādaśī: the northern gate'),
 sources([('Texts:','Padma Purāṇa, Uttara Khaṇḍa (Ekādaśī and Mura, as told in our Ekādaśī series); Bhagavad Gītā 10.35 and 18.66 (our Gītā pages); Śāntākāraṃ (our page).'),('Temples and customs:','Śrīraṅgam Adhyayana Utsava, Paramapada vāsal, Araiyar sēvai, Tirumala’s ten-day Vaikuṇṭha dvāra darśan, Bhadrācalam’s uttara dvāra darśana, as summarised in our earlier guide from temple and press sources; Wikipedia, “Vaikuntha Ekadashi”.')],'the Madhu–Kaiṭabha origin of the gate (temple tradition); the dates of the Āḻvārs (scholarly estimates vary); the antiquity of the Śrīraṅgam rite (temple chronicles); Tirumala’s current darśan arrangements (subject to change).','Interpretations are marked as such.')]
build(i,'MUKKOṬI · THE NORTHERN GATE · GĪTĀ JAYANTĪ',COV,'The gate opens before dawn','What <b>Ekādaśī</b> is and why this one is the greatest, the <b>northern gate</b> and its story, <b>Śrīraṅgam</b>’s songs and Tirumala, the fast and vigil, and three <b>verses</b> for the day.','Vaikuṇṭha Ekādaśī explained: Mārgaśīrṣa Śukla Ekādaśī and the goddess Ekādaśī, Gītā 10.35 on the best of months, the Vaikuṇṭha dvāra and the Madhu–Kaiṭabha story, Śrīraṅgam’s Adhyayana Utsava and the Āḻvārs, Tirumala, the fast and vigil, Śāntākāraṃ, and Gītā Jayantī with Gītā 18.66.',pp)
print('vk ok',len(pp)+2)
